function describe(value: string | number): string {
  if (typeof value === "string") {
    return value.toUpperCase();
  }
  return `Число: ${value}`;
}
console.log(describe("hello"));

function double(number: number): number {
  return number * 2;
}
console.log(double(6));

interface Student {
  name: string;
  points: number;
}
const student: Student = { name: "Аня", points: 80 };
console.log(student.name);

interface Student { name: string; bio?: string; }
const student: Student = { name: "Лев" };
console.log(student.bio ?? "Описание не добавлено");

type Status = "loading" | "ready" | "error";
function label(status: Status): string {
  if (status === "ready") return "Готово";
  if (status === "loading") return "Загрузка";
  return "Ошибка";
}
console.log(label("ready"));

function first<T>(items: T[]): T | undefined {
  return items[0];
}
const value = first<string>(["Python", "Go"]);
console.log(value ?? "Пусто");

function positive(value: unknown): number | null {
  if (typeof value !== "number") return null;
  if (!Number.isFinite(value) || value < 0) return null;
  return value;
}
console.log(positive("10"));

interface Lesson { title: string; done: boolean; }
function countDone(lessons: Lesson[]): number {
  let count = 0;
  for (const lesson of lessons) {
    if (lesson.done) count += 1;
  }
  return count;
}
console.log(countDone([{ title: "Типы", done: true }]));

type Named = { name: string };
function greet(value: Named): string { return value.name; }
const user = { name: "Ann", age: 20 };
console.log(greet(user));

type Result = { ok: true; value: number } | { ok: false; error: string };
function show(result: Result): string {
  return result.ok ? String(result.value) : result.error;
}
console.log(show({ ok: true, value: 3 }));

function first<T>(items: readonly T[]): T | undefined {
  return items[0];
}
console.log(first([1, 2]));

function pick<T, K extends keyof T>(value: T, key: K): T[K] {
  return value[key];
}
console.log(pick({ name: "Ann", age: 20 }, "age"));

type Flags<T> = { [K in keyof T]: boolean };
type User = { name: string; age: number };
const enabled: Flags<User> = { name: true, age: false };
console.log(enabled);

type ElementOf<T> = T extends readonly (infer U)[] ? U : never;
type Value = ElementOf<readonly number[]>;
const value: Value = 5;
console.log(value);

type User = { id: number };
function isUser(value: unknown): value is User {
  return typeof value === "object" && value !== null && "id" in value && typeof value.id === "number";
}
console.log(isUser({ id: 1 }));

type UserId = string & { readonly __brand: "UserId" };
function userId(raw: string): UserId {
  if (!raw.startsWith("u_")) throw new Error("invalid id");
  return raw as UserId;
}
console.log(userId("u_7"));

type Loaded<T> = { ok: true; data: T } | { ok: false; message: string };
async function load(): Promise<Loaded<number>> {
  return { ok: true, data: 7 };
}
load().then(console.log);

type Handler<T> = (value: T) => void;
function visit(items: readonly string[], handler: Handler<string>) {
  for (const item of items) handler(item);
}
visit(["a"], console.log);

function double(value: number): number { return value * 2; }
const result: number = double(3);
// @ts-expect-error string is not accepted
double("3");
console.log(result);

export type Config = { readonly apiUrl: string };
export function endpoint(config: Config, path: string): string {
  return new URL(path, config.apiUrl).href;
}

type V1 = { id: string; name: string };
type V2 = V1 & { displayName?: string };
function label(user: V2): string { return user.displayName ?? user.name; }
console.log(label({ id: "1", name: "Ann" }));

type State = { kind: "idle" } | { kind: "ready"; value: number };
type Event = { kind: "loaded"; value: number } | { kind: "reset" };
function reduce(state: State, event: Event): State {
  return event.kind === "reset" ? { kind: "idle" } : { kind: "ready", value: event.value };
}

export interface UserReader {
  find(id: string): Promise<{ id: string; name: string } | null>;
}
export async function nameOf(reader: UserReader, id: string) {
  return (await reader.find(id))?.name ?? null;
}

type Command = { kind: "create"; id: string };
type Reply = { ok: true; id: string } | { ok: false; reason: string };
function handle(command: Command, ids: Set<string>): Reply {
  if (ids.has(command.id)) return { ok: false, reason: "duplicate" };
  ids.add(command.id);
  return { ok: true, id: command.id };
}
